package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.lang.reflect.*;
import java.util.*;

/** Independent filtered joint-mixture objective and every emission-logit numerical derivative. */
public final class R26DurationDiagnosticsTest {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static Field field(String name)throws Exception{Field f=FamilyF09KernelR26.class.getDeclaredField(name);f.setAccessible(true);return f;}
    static double[][] matrix(FamilyF09KernelR26 m,String name)throws Exception{return (double[][])field(name).get(m);}
    static double[][] clone(double[][] values){double[][] result=new double[values.length][];for(int i=0;i<values.length;i++)result[i]=values[i].clone();return result;}
    static byte[] save(FamilyF09KernelR26 m)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();m.write(new DataOutputStream(b));return b.toByteArray();}
    static FamilyF09KernelR26 restore(byte[] bytes)throws IOException{FamilyF09KernelR26 m=new FamilyF09KernelR26();m.read(new DataInputStream(new ByteArrayInputStream(bytes)));return m;}
    static int[] draw(Random random){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int q=random.nextInt(i+1),v=d[q];d[q]=d[i];d[i]=v;}return d;}
    static double objective(FamilyF09KernelR26 model,double[][] prior,int[] draw)throws Exception{
        double[][] parameters=matrix(model,"logits");double[] likelihood=new double[3],mass=new double[3];double maximum=Double.NEGATIVE_INFINITY,regularizer=0;
        for(int s=0;s<3;s++){double[][] scores=new double[10][10];for(int p=0;p<10;p++)for(int n=0;n<10;n++)scores[p][n]=parameters[s][10*p+n];double log= -ExactPermutationR26.infer(scores,null).logZ;for(int p=0;p<10;p++)log+=scores[p][draw[p]-1];likelihood[s]=log;maximum=Math.max(maximum,log);for(double x:prior[s])mass[s]+=x;for(double x:parameters[s])regularizer+=.5e-5*x*x;}
        double z=0;for(int s=0;s<3;s++)z+=mass[s]*Math.exp(likelihood[s]-maximum);return -maximum-Math.log(z)+regularizer;
    }
    public static void main(String[] args)throws Exception{
        double maximumError=0;int checks=0;
        for(int mode=0;mode<3;mode++){
            Random random=new Random(260909+mode);FamilyF09KernelR26 model=new FamilyF09KernelR26();if(mode>0)for(int i=0;i<12;i++)model.update(draw(random));if(mode==2)model.resetTemporalContext();double[][] parameters=matrix(model,"logits");for(double[] row:parameters)for(int i=0;i<row.length;i++)row[i]=(random.nextDouble()-.5)*.2;
            byte[] originalBytes=save(model);long beforeUpdates=model.completedTrainingUpdates();double[][] old=clone(parameters),prior=clone(matrix(model,"prior")),oldExit=clone(matrix(model,"exit")),oldStay=clone(matrix(model,"stay"));int[] target=draw(random);double before=objective(model,prior,target);model.update(target);TrainingDiagnosticsR26.Step step=model.lastTrainingStep();check(step.update==beforeUpdates+1&&Math.abs(before-step.lossBefore)<1e-10,"Filtered before loss or lifetime differs");check(Math.abs(objective(model,prior,target)-step.lossAfter)<1e-10,"After objective consumed revealed filtering prior");
            double[][] after=matrix(model,"logits"),gradient=new double[3][100];double norm=0,delta=0;for(int s=0;s<3;s++)for(int j=0;j<100;j++){check(Math.abs(after[s][j])<8,"Derivative fixture clipped");gradient[s][j]=(old[s][j]-after[s][j])/.03;norm+=gradient[s][j]*gradient[s][j];double d=after[s][j]-old[s][j];delta+=d*d;}for(int s=0;s<3;s++)for(int d=0;d<32;d++){double a=matrix(model,"exit")[s][d]-oldExit[s][d],b=matrix(model,"stay")[s][d]-oldStay[s][d];delta+=a*a+b*b;}check(Math.abs(Math.sqrt(norm)-step.gradientNorm)<1e-10&&Math.abs(Math.sqrt(delta)-step.parameterDeltaNorm)<1e-12,"Emission gradient or complete learned parameter delta differs");
            FamilyF09KernelR26 original=restore(originalBytes);double[][] values=matrix(original,"logits");for(int s=0;s<3;s++)for(int j=0;j<100;j++){double eps=1e-5,x=values[s][j];values[s][j]=x+eps;double plus=objective(original,prior,target);values[s][j]=x-eps;double minus=objective(original,prior,target);values[s][j]=x;double error=Math.abs((plus-minus)/(2*eps)-gradient[s][j]);maximumError=Math.max(maximumError,error);checks++;check(error<2e-6,"Filtered joint mixture derivative differs: "+error);}
            check(Arrays.equals(originalBytes,save(original)),"Objective oracle changed original state");original.update(draw(random));check(step.inputHash.equals(original.lastTrainingStep().inputHash),"Input hash observed target");FamilyF09KernelR26 copy=restore(save(model));check(copy.lastTrainingStep()==null,"Restored stale measurement");int[] next=draw(random);model.update(next);copy.update(next);check(Arrays.equals(save(model),save(copy)),"Full next update differs");long updates=model.completedTrainingUpdates();double[][] learned=clone(matrix(model,"logits")),durations=clone(matrix(model,"exit"));model.resetTemporalContext();check(model.completedTrainingUpdates()==updates&&model.lastTrainingStep()==null,"Gap reset lifetime or stale measurement");check(Arrays.deepEquals(learned,matrix(model,"logits"))&&Arrays.deepEquals(durations,matrix(model,"exit")),"Gap erased learned parameters");copy=restore(save(model));next=draw(random);model.update(next);copy.update(next);check(Arrays.equals(save(model),save(copy)),"Gap restore/next update differs");
            byte[] unchanged=save(model),bad=unchanged.clone();Arrays.fill(bad,bad.length-8,bad.length,(byte)0xff);try{model.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("Nonfinite restored state accepted");}catch(IOException expected){}check(Arrays.equals(unchanged,save(model)),"Rejected restore changed parameters or state");boolean canceled=false;for(int operations:new int[]{1,100,10000}){model.read(new DataInputStream(new ByteArrayInputStream(unchanged)));ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,operations,()->false));try{model.update(target);}catch(BudgetTokenSU1.Yield expected){canceled=true;check(Arrays.equals(unchanged,save(model))&&model.lastTrainingStep()==null,"Interrupted duration update partially committed");}finally{ExecutionBudgetR26.leave();}}check(canceled,"Cooperative interruption not observed");
            if(args.length>0&&mode==1)java.nio.file.Files.write(java.nio.file.Paths.get(args[0]),save(model));
        }
        System.out.println("R26_DURATION_DIAGNOSTICS_PASS|causalContexts=3|numericCoordinates="+checks+"|maxDerivativeError="+maximumError+"|filteredJointMixturePlusLogitL2=true|fixedPreLabelPrior=true|gradientScopeEmissionLogits=true|durationExpectedCountsIncludedInDelta=true|restoreNextGapCancelAtomic=true|scope=SYNTHETIC_KERNEL_NOT_NATURAL_QUALITY");
    }
}
